-- Arbeitsrecht Berufsbildung > Rechte von Arbeitgebern > Kündigung unter Einhaltung der Vorschriften (§ 22 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb einen Fachinformatiker während der Probezeit ohne Angabe von Gründen kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies in der Probezeit"}, {"text": "Nein", "correct": false, "because": "Probezeit erfordert keine Begründung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Kündigung eines Fachinformatikers nach der Probezeit schriftlich erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsbetrieb einen Fachinformatiker nach der Probezeit ohne wichtigen Grund kündigen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt einen wichtigen Grund"}, {"text": "Ja", "correct": false, "because": "Nach Probezeit ist ein Grund erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker während der Probezeit jederzeit kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies ohne Grund"}, {"text": "Nein", "correct": false, "because": "Kündigungsfreiheit gilt in der Probezeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb bei einer Kündigung eines Fachinformatikers Fristen einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG legt Kündigungsfristen fest"}, {"text": "Nein", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt die Kündigung eines Fachinformatikers durch den Arbeitgeber?', 2, '[{"text": "§ 22 BBiG", "correct": true, "because": "Regelt die Kündigungsvorschriften"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Kündigungsfrist für einen Fachinformatiker nach der Probezeit bei ordentlicher Kündigung?', 3, '[{"text": "4 Wochen zum Monatsende", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}, {"text": "2 Wochen jederzeit", "correct": false, "because": "Nur in der Probezeit"}, {"text": "Sofort ohne Frist", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund rechtfertigt eine außerordentliche Kündigung eines Fachinformatikers?', 3, '[{"text": "Wiederholte Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG sieht dies als wichtigen Grund"}, {"text": "Unzufriedenheit des Ausbilders", "correct": false, "because": "Kein wichtiger Grund"}, {"text": "Einmalige Verspätung", "correct": false, "because": "Nicht ausreichend schwerwiegend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann einen Fachinformatiker während der Ausbildung kündigen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 22 BBiG gibt dem Arbeitgeber dieses Recht"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat kein Kündigungsrecht"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb tun, wenn er einen Fachinformatiker außerordentlich kündigen will?', 3, '[{"text": "Die Kündigung schriftlich begründen", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform und Grund"}, {"text": "Mündlich kündigen", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Die IHK um Erlaubnis bitten", "correct": false, "because": "Nicht erforderlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen müssen für eine Kündigung eines Fachinformatikers nach der Probezeit erfüllt sein?', 4, '[{"text": "Wichtiger Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Schriftform", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Mündliche Absprache", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Einhaltung der Kündigungsfrist", "correct": true, "because": "Bei ordentlicher Kündigung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe können eine außerordentliche Kündigung eines Fachinformatikers rechtfertigen?', 3, '[{"text": "Wiederholtes Schwänzen der Berufsschule", "correct": true, "because": "Schwerwiegende Pflichtverletzung"}, {"text": "Diebstahl von Betriebseigentum", "correct": true, "because": "Wichtiger Grund gemäß § 22 Abs. 2"}, {"text": "Einmalige Unpünktlichkeit", "correct": false, "because": "Nicht schwerwiegend genug"}, {"text": "Verletzung der Verschwiegenheit", "correct": true, "because": "Schwere Pflichtverletzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb bei der Kündigung eines Fachinformatikers beachten?', 4, '[{"text": "Schriftform einhalten", "correct": true, "because": "§ 22 Abs. 2 BBiG schreibt dies vor"}, {"text": "Kündigungsfristen wahren", "correct": true, "because": "Bei ordentlicher Kündigung erforderlich"}, {"text": "Mündliche Ankündigung genügt", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Wichtigen Grund angeben", "correct": true, "because": "Nach Probezeit notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Fachinformatiker bei einer Kündigung durch den Betrieb?', 3, '[{"text": "Fristgerechte Kündigung erwarten", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt vor willkürlicher Kündigung"}, {"text": "Schriftliche Begründung verlangen", "correct": true, "because": "Nach Probezeit vorgeschrieben"}, {"text": "Sofortige Wiedereinstellung fordern", "correct": false, "because": "Kein automatisches Recht"}, {"text": "Kündigungsschutzklage einreichen", "correct": true, "because": "Möglich bei unrechtmäßiger Kündigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Situationen erlauben eine Kündigung eines Fachinformatikers ohne Frist?', 3, '[{"text": "Schwere Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt außerordentliche Kündigung"}, {"text": "Betriebsstilllegung", "correct": true, "because": "Wichtiger Grund"}, {"text": "Einmaliges Fehlverhalten", "correct": false, "because": "Nicht ausreichend schwerwiegend"}, {"text": "Wiederholte Pflichtverletzung", "correct": true, "because": "Kann außerordentlich sein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Ausbildungsbetrieb kann einen Fachinformatiker in der Probezeit ohne Grund kündigen. b) Nach der Probezeit ist kein Grund erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Probezeit erfordert keinen Grund, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Kündigung nach der Probezeit muss schriftlich sein. b) Ein wichtiger Grund ist nach der Probezeit erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform und Grund"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann in der Probezeit mit 2 Wochen Frist kündigen. b) Nach der Probezeit kann der Betrieb ohne Frist kündigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Probezeit erlaubt kurze Frist, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine außerordentliche Kündigung erfordert einen wichtigen Grund. b) Die Kündigungsfrist beträgt immer 4 Wochen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtiger Grund nötig, b) gilt nur für ordentliche Kündigung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ausbildungsbetrieb muss einen Fachinformatiker schriftlich kündigen. b) Eine Kündigung in der Probezeit muss begründet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

